      function latestNewsPanel(){const data=dashboardData.news,items=data?.articles||[];const body=items.length?`<div class="dashboard-news-list">${items.map(function(item){const dateText=new Date(item.timestamp).toLocaleString('id-ID',{dateStyle:'medium',timeStyle:'short'});return `<article class="dashboard-news-item"><button type="button" class="dashboard-news-open" data-action="open-news" data-news-title="${escapeHTML(item.title)}">${escapeHTML(item.title)}</button><small>${escapeHTML(item.symbols.join(', ')||item.sector||'IDX')} · ${escapeHTML(dateText)} · via snapshot Sectors.app</small></article>`}).join('')}</div><p class="dashboard-meta">Ini berita dari snapshot lokal Sectors, bukan feed real-time. Snapshot terakhir mencakup sampai ${escapeHTML(data.coverage_end||'—')}.</p>`:`<div class="dashboard-placeholder"><div><strong>Berita belum tersedia</strong>${escapeHTML(data?.issues?.[0]||'Tidak ada artikel pada snapshot lokal yang dapat ditampilkan.')}</div></div>`;return section('Latest News',body,btn('Buka Market Universe','go-market'))}
      function dashboard(){return pageHead('Dashboard','Ringkasan kondisi pasar dan emiten untuk membantu menentukan area riset prioritas.',btn('Segarkan data lokal','refresh-dashboard')+btn('Sumber & metode · PDF','go-sources'))+`<div class="dashboard-layout"><div class="dashboard-alerts">${dashboardFlowSummary()}${marketRegimePanel(true)}${screenerMarketBreadth(true)}${dashboardCapitalizationSummary()}</div><div class="dashboard-indices">${ihsgPanel()}${lq45IndexPanel()}</div><div class="dashboard-bottom">${signalBaselinePanel()}${latestNewsPanel()}</div><details class="dashboard-stock-list"><summary>Daftar 45 emiten · urutan alfabetis · buka Screener untuk analisis lengkap</summary><div class="screener-toolbar"><input id="dashboard-screener-search" placeholder="Cari ticker / nama emiten" aria-label="Cari ticker atau nama emiten"><button class="filter" data-action="go-screener">Buka Screener →</button></div><p class="dashboard-meta">Daftar ini bukan ranking; metrik screener yang belum dihitung tetap ditandai secara eksplisit.</p>${screenerTable()}</details></div>`}
      function market(){const d=dashboardData.ihsg;return pageHead('Market Overview','IHSG, kondisi pasar, dan konteks untuk membaca evidence emiten',btn('Segarkan data lokal','refresh-dashboard'))+`<div class="metrics">${metric('IHSG terakhir',d?.ok?Number(d.latest_price).toLocaleString('id-ID',{minimumFractionDigits:3,maximumFractionDigits:3}):'Belum tersedia',d?.ok?'Penutupan '+d.coverage_end:'Snapshot lokal belum terbaca')}${metric('Perubahan harian',d?.ok?(d.daily_change_pct>=0?'+':'')+Number(d.daily_change_pct).toFixed(2)+'%':'Belum tersedia',d?.ok?'Dihitung dari dua penutupan terakhir':'Butuh minimal dua observasi')}${metric('Cakupan IHSG',d?.ok?d.observation_count+' observasi':'Belum tersedia',d?.ok?d.coverage_start+' sampai '+d.coverage_end:'Periksa snapshot lokal')}${metric('Regime / breadth','Belum dihitung','Aturan dan perhitungan belum dijalankan')}</div><div class="split">${ihsgPanel()}${section('Breadth & regime',`<div class="dashboard-placeholder"><div><strong>Belum dihitung</strong>IHSG tersedia sebagai benchmark indeks; breadth LQ45 perlu menghitung return konstituen pada tanggal yang sama dan mencatat coverage.</div></div>`,btn('Buka screener','go-screener'))}</div>${section('Provenance IHSG',`<p class="note">Sumber: Sectors.app v2 · ${d?.snapshot_count||0} snapshot lokal · ${d?.observation_count||0} observasi · hash dan status HTTP diverifikasi · retrieval terakhir ${escapeHTML(d?.retrieved_at||'belum tersedia')}.</p><p class="note">Perubahan harian hanya deskriptif. Belum ada klasifikasi regime, forecast, atau sinyal.</p>`,btn('Lihat Data Library','go-library'))}`}
      let signalBaselineCost=10;
      function dashboardFlowSummary(){
        const f=dashboardData.foreign_flow,items=f?.unusual_foreign_flow||[],latest=f?.daily?.at(-1);
        if(!latest)return section('Unusual Flow','<p class="dashboard-meta">Memuat snapshot arus asing lokal…</p>',btn('Detail pasar','go-market'),'dashboard-flow-summary');
        const rows=items.slice(0,3).map(item=>{const z=Number(item.z20),width=Math.min(50,Math.abs(z)/3*50),color=z<0?'#e4777b':'#49c99e';return `<div class="dashboard-mini-z" aria-label="${escapeHTML(item.ticker)} Z ${z.toFixed(2)}"><b>${escapeHTML(item.ticker)}</b><div class="dashboard-mini-z-track"><i style="left:${z<0?50-width:50}%;width:${width}%;background:${color}"></i></div><b style="color:${color}">${z>=0?'+':''}${z.toFixed(2)}</b></div>`}).join('');
        return section('Unusual Flow',`<div class="dashboard-summary-kpi" style="color:var(--cyan)">${items.length} emiten</div><div class="dashboard-meta">Anomali arus asing · |Z| ≥ 2 · pembanding 20 sesi</div>${rows||'<p class="dashboard-meta">Tidak ada emiten melewati ambang.</p>'}<p class="dashboard-meta">${escapeHTML(latest.date)} · ${latest.coverage}/${f.universe_count} emiten · ${items.length>3?'3 dari '+items.length+' ditampilkan · ':''}Z negatif ← 0 → positif; batang dibatasi ±3.<br>Arus asing, bukan broker atau sinyal beli/jual.</p>`,btn('Detail pasar','go-market'),'dashboard-flow-summary');
      }
      function dashboardCapitalizationSummary(){
        const v=dashboardData.valuation_readiness,cap=v?.market_cap_idr,total=v?.universe_count||45,count=v?.market_cap_coverage||0;
        if(!Number.isFinite(cap)||cap<=0||!count)return section('Market capitalization · LQ45','<p class="dashboard-meta">Kapitalisasi snapshot lokal belum tersedia.</p>',btn('Detail pasar','go-market'),'dashboard-cap-summary');
        const dates=[...new Set((v.forward_pe_by_issuer||[]).map(row=>row.price_as_of).filter(Boolean))].sort(),date=dates.length===1?dates[0]:dates.length?dates[0]+'–'+dates.at(-1):'Tanggal laporan belum tersedia';
        return section('Market capitalization · LQ45',`<div class="dashboard-summary-kpi" style="color:#62bcf7">Rp ${rupiahCompact(cap)}</div><div class="dashboard-meta">Agregat ${count}/${total} emiten snapshot</div><div class="dashboard-summary-pair"><span>Cakupan nilai</span><b>${Math.round(count/total*100)}%</b></div><div class="screener-breadth-bar" role="img" aria-label="${count} dari ${total} kapitalisasi emiten tersedia"><span style="width:${count/total*100}%;background:#62bcf7"></span><span style="width:${(total-count)/total*100}%;background:#8192a7"></span></div><p class="dashboard-meta">Harga report ${escapeHTML(date)} · bukan total kapitalisasi IDX atau data historis.</p>`,btn('Detail pasar','go-market'),'dashboard-cap-summary');
      }
      function signalBaselineChart(rows){
        const W=680,H=276,L=54,R=18,T=18,B=44;
        const values=[0,...rows.flatMap(row=>[row.signal_wealth-1,row.market_wealth-1])];
        const low=Math.min(...values),high=Math.max(...values),padding=Math.max(.015,(high-low)*.1),min=low-padding,max=high+padding;
        const x=i=>L+i/(rows.length-1)*(W-L-R),y=value=>T+(max-value)/(max-min)*(H-T-B);
        const pct=value=>(value>=0?'+':'')+(value*100).toFixed(1)+'%';
        const grid=[min,(min+max)/2,max,0].sort((a,b)=>a-b).filter((value,i,all)=>i===0||Math.abs(value-all[i-1])>.01).map(value=>`<line x1="${L}" y1="${y(value)}" x2="${W-R}" y2="${y(value)}" stroke="${value===0?'#7c92a6':'#284054'}" stroke-dasharray="${value===0?'0':'4 5'}"/><text x="${L-8}" y="${y(value)+4}" text-anchor="end" fill="#9aacbf" font-size="12">${pct(value)}</text>`).join('');
        const line=(field,color,dash='')=>`<polyline points="${rows.map((row,i)=>`${x(i).toFixed(2)},${y(row[field]-1).toFixed(2)}`).join(' ')}" fill="none" stroke="${color}" stroke-width="1.5" stroke-dasharray="${dash}"/>`;
        const marks=rows.map((row,i)=>{const label=`Sinyal ${pct(row.signal_wealth-1)} · IHSG ${pct(row.market_wealth-1)} · Selisih ${((row.signal_wealth-row.market_wealth)*100).toFixed(1)} pp · ${row.position==null?'Awal evaluasi':row.position?'Eksposur IHSG':'Kas'}${row.signal_date?' · Observasi sinyal '+row.signal_date:''}`;return `<circle data-chart-point data-chart-x="${x(i).toFixed(2)}" data-chart-y="${y(row.signal_wealth-1).toFixed(2)}" data-date="${escapeHTML(row.date)}" data-label="Return kumulatif" data-value="${escapeHTML(label)}" data-unit="" cx="${x(i)}" cy="${y(row.signal_wealth-1)}" r="3" fill="transparent"/>`}).join('');
        const ticks=[0,Math.floor((rows.length-1)/2),rows.length-1].map((i,j)=>`<text x="${x(i)}" y="${H-16}" text-anchor="${j===0?'start':j===2?'end':'middle'}" fill="#9aacbf" font-size="12">${escapeHTML(rows[i].date)}</text>`).join('');
        return `<div class="signal-baseline-chart-frame"><svg class="signal-baseline-chart" data-chart-interaction viewBox="0 0 ${W} ${H}" tabindex="0" role="img" aria-label="Return kumulatif aturan regime IHSG dan IHSG buy-and-hold pada tanggal yang sama, ${rows[0].date} sampai ${rows.at(-1).date}. Gunakan panah kiri/kanan untuk tanggal dan nilai.">${grid}${line('market_wealth','#6aa9ed','6 4')}${line('signal_wealth','#44cdb4')}${marks}${ticks}</svg></div>`;
      }
      function signalBaselinePanel(){
        const data=dashboardData.signal_baseline,ihsg=dashboardData.ihsg;
        const blocked=message=>section('Signal vs Market Baseline',`<div class="dashboard-placeholder"><div><strong>Perbandingan belum dapat ditampilkan</strong>${escapeHTML(message)}</div></div>`,'DATA REQUIRED','signal-baseline-panel');
        if(!data)return blocked(dashboardData.loading?'Memuat perhitungan dari snapshot IHSG lokal…':'Artefak uji historis belum tersedia pada snapshot lokal.');
        if(!data.ok)return blocked(data.reason||'Histori IHSG belum cukup.');
        if(data.schema_version!=='ihsg-regime-baseline.v1'||!ihsg?.ok||data.source_fingerprint!==ihsg.series_fingerprint||data.source_coverage_end!==ihsg.coverage_end||data.observation_count!==ihsg.observation_count)return blocked('Perhitungan dan snapshot IHSG aktif berbeda; segarkan data lokal.');
        const result=data.cases.find(item=>item.cost_bps===signalBaselineCost)||data.cases.find(item=>item.cost_bps===10);
        if(!result?.path?.length)return blocked('Lintasan historis belum tersedia.');
        const fmt=value=>(value>=0?'+':'')+(value*100).toFixed(1)+'%',pp=value=>(value>=0?'+':'')+(value*100).toFixed(1)+' pp';
        const stats=[['Sinyal regime',fmt(result.signal.cumulative_return),'#44cdb4'],['IHSG buy-and-hold',fmt(result.market.cumulative_return),'#6aa9ed'],['Selisih',pp(result.excess_cumulative),result.excess_cumulative<0?'#ed8589':'#44cdb4']].map(([label,value,color])=>`<div><small>${label}</small><strong style="color:${color}">${value}</strong></div>`).join('');
        const interval=result.interval,ci=interval.lower==null?'Interval belum tersedia; jumlah return kurang.':`Selisih rerata return harian × 252: ${pp(interval.estimate)}/tahun; interval 95% ${pp(interval.lower)} hingga ${pp(interval.upper)}/tahun. ${interval.lower<=0&&interval.upper>=0?'Interval melintasi nol; keunggulan belum jelas.':interval.upper<0?'Interval pada sampel ini berada di bawah nol.':'Interval pada sampel ini berada di atas nol.'}`;
        const quarters=result.quarterly.map(row=>`<tr><td>${row.period}<small>${row.sessions} sesi</small></td><td>${fmt(row.signal_return)}</td><td>${fmt(row.market_return)}</td><td style="color:${row.excess<0?'#ed8589':'#44cdb4'}">${pp(row.excess)}</td></tr>`).join('');
        const body=`<div class="signal-baseline-toolbar"><span class="sub">${result.path[0].date}–${result.path.at(-1).date} · ${result.sessions} return</span><label>Biaya satu arah <select id="signal-baseline-cost" aria-label="Asumsi biaya per pergantian eksposur">${data.cases.map(item=>`<option value="${item.cost_bps}" ${item.cost_bps===result.cost_bps?'selected':''}>${item.cost_bps===0?'Bruto · 0 bps':item.cost_bps+' bps'}</option>`).join('')}</select></label></div><div class="signal-baseline-stats">${stats}</div><p class="signal-baseline-verdict">${result.excess_cumulative<0?'Sinyal tertinggal dari IHSG pada sampel ini.':result.excess_cumulative>0?'Sinyal unggul dari IHSG pada sampel ini.':'Sinyal dan IHSG setara pada sampel ini.'}</p><div class="signal-baseline-rule">Aturan: eksposur IHSG jika close &gt; SMA 200 dan SMA 50 &gt; SMA 200; selain itu kas. Jeda eksekusi: satu sesi penuh setelah observasi sinyal.</div>${signalBaselineChart(result.path)}<div class="flow-legend"><span><i style="background:#44cdb4"></i>Sinyal regime</span><span><i style="background:#6aa9ed"></i>IHSG buy-and-hold · garis putus</span></div><p class="note">Sumbu Y: return kumulatif sejak awal evaluasi. Hover atau tombol panah menampilkan tanggal, kedua nilai, dan eksposur. ${Math.round(result.exposure_share*100)}% sesi terekspos IHSG · ${result.position_changes} pergantian eksposur.</p><details class="signal-baseline-details"><summary>Hasil per periode, risiko & metode</summary><div class="table-wrap"><table><thead><tr><th>Metrik</th><th>Sinyal</th><th>IHSG</th></tr></thead><tbody><tr><td>CAGR</td><td>${fmt(result.signal.annualized_return)}</td><td>${fmt(result.market.annualized_return)}</td></tr><tr><td>Volatilitas p.a.</td><td>${fmt(result.signal.annualized_volatility)}</td><td>${fmt(result.market.annualized_volatility)}</td></tr><tr><td>Max drawdown</td><td>${fmt(result.signal.max_drawdown)}</td><td>${fmt(result.market.max_drawdown)}</td></tr></tbody></table></div><p class="note">${ci} Bootstrap berpasangan ${interval.simulations||0} kali, blok ${interval.block_sessions||20} sesi, pada lintasan teramati; interval bersifat eksploratoris.</p><div class="table-wrap"><table><thead><tr><th>Periode*</th><th>Sinyal</th><th>IHSG</th><th>Selisih</th></tr></thead><tbody>${quarters}</tbody></table></div><p class="note">*Kuartal pertama/terakhir dapat parsial. Sinyal tertinggal pada ${result.negative_periods}/${result.quarterly.length} periode. Parameter 50/200 tetap, tanpa training atau pencarian parameter.</p><p class="note">Sumber Sectors.app · ${data.observation_count} penutupan, ${data.source_coverage_start}–${data.source_coverage_end}; ${data.warmup_sessions} sesi pemanasan. Price index; IHSG digunakan sebagai proksi riset. Biaya ${result.cost_bps} bps = ${(result.cost_bps/100).toFixed(2)}% setiap perubahan eksposur; IHSG buy-and-hold dikenai biaya masuk yang sama sekali. Kas menghasilkan 0%, dividen/biaya produk aktual dan likuidasi akhir belum dimodelkan. Ini uji rolling historis aturan sederhana; belum membuktikan alpha atau kinerja ke depan.</p></details>`;
        return section('Signal vs Market Baseline',body,'UJI HISTORIS · EKSPLORATORIS','signal-baseline-panel');
      }
      function mountSignalBaselineControls(){
        const select=main.querySelector('#signal-baseline-cost');
        if(select)select.addEventListener('change',()=>{signalBaselineCost=Number(select.value);render();main.querySelector('#signal-baseline-cost')?.focus()});
      }
      function screenerMarketBreadth(compact=false){
        const daily=dashboardData.lq45_daily||{},tickers=screenerRows().map(row=>row.ticker),indexDates=(dashboardData.lq45_index?.series||[]).map(row=>row.date).filter(Boolean);
        const dates=[...new Set(indexDates)].sort(),currentDate=dates.at(-1),previousDate=dates.at(-2),seriesByTicker=new Map();
        tickers.forEach(ticker=>{const source=daily[ticker];if(!source?.ok)return;const rows=new Map((source.series||[]).filter(row=>Number.isFinite(Number(row.close))&&Number(row.close)>0).map(row=>[row.date,Number(row.close)]));seriesByTicker.set(ticker,rows)});
        const minimumCoverage=Math.ceil(tickers.length*.7),need=`Snapshot harga emiten atau indeks LQ45 lokal belum tersedia.`;
        if(!currentDate||!previousDate)return section('Market Breadth · LQ45',`<div class="dashboard-placeholder"><div><strong>Breadth belum dapat dihitung</strong>${need}</div></div>`,'DATA REQUIRED','screener-breadth-overview');
        const currentRows=tickers.filter(ticker=>seriesByTicker.get(ticker)?.has(currentDate)),pairRows=tickers.flatMap(ticker=>{const rows=seriesByTicker.get(ticker),current=rows?.get(currentDate),previous=rows?.get(previousDate);return current!=null&&previous!=null?[{ticker,rows,current,previous,change:current/previous-1}]:[]});
        if(pairRows.length<minimumCoverage)return section('Market Breadth · LQ45',`<div class="dashboard-placeholder"><div><strong>Cakupan belum cukup</strong>Hanya ${pairRows.length}/${tickers.length} emiten punya harga pada kedua tanggal indeks ${previousDate} dan ${currentDate}; batas minimum yang dipakai 70%.</div></div>`,'INSUFFICIENT COVERAGE','screener-breadth-overview');
        const advancers=pairRows.filter(row=>row.change>0).length,decliners=pairRows.filter(row=>row.change<0).length,unchanged=pairRows.length-advancers-decliners,coverage=pairRows.length/tickers.length*100;
        const aboveCount=period=>{const eligible=tickers.flatMap(ticker=>{const rows=seriesByTicker.get(ticker),close=rows?.get(currentDate);if(close==null)return[];const history=[...rows.entries()].filter(([date])=>date<=currentDate).sort((a,b)=>a[0].localeCompare(b[0])).slice(-period).map(([,value])=>value);return history.length===period?[close>history.reduce((sum,value)=>sum+value,0)/period]:[]});return {count:eligible.filter(Boolean).length,total:eligible.length}};
        const sma20=aboveCount(20),sma50=aboveCount(50),pct=(value,total)=>total?100*value/total:0;
        if(compact)return section('Market Breadth · LQ45',`<div class="dashboard-summary-counts"><span><small>Naik</small><b class="positive">${advancers}</b></span><span><small>Tetap</small><b>${unchanged}</b></span><span><small>Turun</small><b class="negative">${decliners}</b></span></div><div class="screener-breadth-bar" role="img" aria-label="${advancers} naik, ${unchanged} tetap, ${decliners} turun dari ${pairRows.length} saham"><span style="width:${pct(advancers,pairRows.length)}%;background:#49c99e"></span><span style="width:${pct(unchanged,pairRows.length)}%;background:#8192a7"></span><span style="width:${pct(decliners,pairRows.length)}%;background:#e4777b"></span></div><div class="dashboard-summary-pair"><span>Di atas SMA 50</span><b>${sma50.count}/${sma50.total} · ${pct(sma50.count,sma50.total).toFixed(0)}%</b></div><p class="dashboard-meta">${currentDate} · ${pairRows.length}/${tickers.length} emiten · snapshot LQ45, bukan seluruh IDX.</p>`,btn('Detail di Screener','go-screener'),'dashboard-breadth-summary');
        const body=`<div class="screener-breadth-heading"><div><strong>${advancers>decliners?'Advancers memimpin':decliners>advancers?'Decliners memimpin':'Pasar berimbang'}</strong><div class="dashboard-meta">Perubahan harian dari ${previousDate} ke ${currentDate} · ${pairRows.length}/${tickers.length} emiten (${coverage.toFixed(0)}%)</div></div><span class="state ${coverage===100?'good':'warn'}">${coverage===100?'FULL COVERAGE':'PARTIAL COVERAGE'}</span></div><div class="screener-breadth-counts"><div class="screener-breadth-count"><small>Naik</small><b style="color:#49c99e">${advancers}</b></div><div class="screener-breadth-count"><small>Tetap</small><b>${unchanged}</b></div><div class="screener-breadth-count"><small>Turun</small><b style="color:#e4777b">${decliners}</b></div></div><div class="screener-breadth-bar" role="img" aria-label="Market breadth tanggal ${currentDate}: ${advancers} saham naik, ${unchanged} tetap, ${decliners} turun dari ${pairRows.length} saham"><span style="width:${pct(advancers,pairRows.length)}%;background:#49c99e"></span><span style="width:${pct(unchanged,pairRows.length)}%;background:#8192a7"></span><span style="width:${pct(decliners,pairRows.length)}%;background:#e4777b"></span></div><div class="screener-breadth-sma">${[['Di atas SMA 20',sma20],['Di atas SMA 50',sma50]].map(([label,item])=>`<div class="screener-breadth-sma-item"><span>${label}</span><div class="screener-breadth-sma-track" role="img" aria-label="${item.count} dari ${item.total} emiten di atas ${label.replace('Di atas ','')}"><span style="width:${pct(item.count,item.total)}%"></span></div><b>${item.count}/${item.total} · ${pct(item.count,item.total).toFixed(0)}%</b></div>`).join('')}</div><p class="note">Breadth mengukur partisipasi saham dalam snapshot universe LQ45 saat ini, bukan seluruh IDX dan bukan komposisi historis LQ45. SMA dihitung per emiten dari penutupan lokal yang tersedia. Snapshot Sectors.app · nilai deskriptif, bukan sinyal beli/jual.</p>`;
        return section('Market Breadth · LQ45',body,'HARIAN · SNAPSHOT LOKAL','screener-breadth-overview');
      }
      function screener(){
        loadSectorHeatmap();
        const analysis=dashboardData.screener_analysis,summary=analysis?.summary;
return pageHead('Screener','Arus asing, hasil event historis, dan regime masing-masing emiten',btn('Sumber & metode · PDF','go-sources'))+taskScreenerSection()+`<div class="screener-toolbar"><input id="screener-search" value="${escapeHTML(screenerFilters.query)}" placeholder="Ticker / nama emiten" aria-label="Cari ticker atau nama emiten"><label class="sub" for="screener-sector-filter">Sektor</label><select class="filter" id="screener-sector-filter" data-screener-filter="sector" aria-label="Filter sektor"><option value="">Semua sektor</option>${screenerSectorOptions()}</select><label class="sub" for="screener-regime-filter">Regime emiten</label><select class="filter" id="screener-regime-filter" data-screener-filter="regime" aria-label="Filter regime emiten"><option value="">Semua regime</option>${['Tren menguat','Tren melemah','Tren campuran','Belum dihitung'].map(label=>`<option value="${label}" ${screenerFilters.regime===label?'selected':''}>${label}</option>`).join('')}</select><button class="action" data-action="screener-reset">Reset</button></div><p class="dashboard-meta">Regime dari close, SMA50 dan SMA200 tiap saham, bukan label IHSG yang disalin. ${summary?`${summary.computed_count}/${summary.issuer_count} emiten dihitung · ${summary.small_sample_count} sampel kecil · ${escapeHTML(analysis.as_of)}`:'Memuat perhitungan snapshot lokal…'}</p>${screenerMarketBreadth()}${section('LQ45 · '+screenerRows().length+' emiten',`<p class="dashboard-meta">Event: net buy asing positif dan Z20 ≥2 terhadap 20 sesi sebelumnya. Entry close sesi berikutnya; hasil rata-rata 5/20 sesi, event tidak overlap. Sample = n5/n20. Hit Rate & CI95 mengukur ungguli IHSG 20D, bukan prediksi. Urutan alfabetis; return bruto historis, bukan total return atau rekomendasi.</p><p class="dashboard-meta" id="screener-result-count" aria-live="polite"></p>${screenerTable()}`,'HISTORIS · STUDI EVENT')}`;
      }
      function issuer(){const company=screenerRows().find(row=>row.ticker===ticker)?.company||ticker,tabs=['Overview','Flow','Evidence','Historical Analog','Event Study','Outcomes'];if(!tabs.includes(issuerTab))issuerTab='Overview';return pageHead(`${ticker} · ${escapeHTML(company)}`,'Issuer dossier • semua tab tetap pada emiten ini',btn('☆ Watchlist','watch')+btn('Report · PDF','export'))+`<div class="tabbar" role="tablist" aria-label="Bagian dossier ${escapeHTML(ticker)}">${tabs.map(t=>`<button id="issuer-tab-${t.toLowerCase().replaceAll(' ','-')}" class="tab ${issuerTab===t?'active':''}" role="tab" aria-selected="${issuerTab===t}" aria-controls="issuer-tab-panel" tabindex="${issuerTab===t?0:-1}" data-action="issuer-tab" data-tab="${t}">${t}</button>`).join('')}</div><div id="issuer-tab-panel" role="tabpanel" aria-labelledby="issuer-tab-${issuerTab.toLowerCase().replaceAll(' ','-')}">${issuerTabContent()}</div>`}
      function flow(){return pageHead('Flow Context','Scope utama: broker activity per emiten + daily price; flow tidak mengungkap beneficial owner atau niat.',btn('Periode 5D ▾','flow-period'))+`<div class="metrics">${metric('Daily OHLCV','FOUND · 45/45','Histori hingga 24 Sep 2026')}${metric('Foreign flow','FOUND · 45/45','Histori provider mulai 2 Jan 2025')}${metric('Broker per emiten','FOUND · scope utama','Gunakan dataset issuer-level yang sudah ditarik')}${metric('Broker archive','Arsip saja','Empat broker terpisah; bukan input produk')}</div>`+section('Status input flow',`<table><thead><tr><th>Input</th><th>Status</th><th>Cakupan</th><th>Peran di produk</th></tr></thead><tbody><tr><td>Daily OHLCV</td><td><span class="state good">FOUND</span></td><td>45 ticker; 585 windows; sampai 24 Sep 2026</td><td>Return, turnover, volatilitas, dan price response</td></tr><tr><td>Foreign flow</td><td><span class="state good">FOUND · histori tersedia</span></td><td>45 ticker; 2 Jan 2025–24 Sep 2026</td><td>Dimensi flow; histori sebelumnya tidak disediakan provider</td></tr><tr><td>Broker activity per emiten</td><td><span class="state good">FOUND · sesuai keputusan tim</span></td><td>Dataset utama issuer-level; tampilkan periode dan provenance dari snapshot aslinya</td><td>Input flow utama; pertahankan timestamp, schema, dan provenance</td></tr><tr><td>Empat broker archive</td><td><span class="state warn">ARSIP SAJA</span></td><td>228 payload YP, XL, ZP, AK</td><td>Tidak dipakai dan tidak menggantikan data per emiten</td></tr></tbody></table>`,`Broker activity adalah jalur transaksi, bukan identitas pemilik manfaat`)+section('Flow vs price',`<p class="note">Analitik flow/persistence dan price response belum dihitung di UI ini. Implementasi menyelaraskan tanggal transaksi yang tersedia, menyimpan versi formula, dan menampilkan periode aktual. Input FOUND tidak berarti fitur analitik sudah tervalidasi.</p>`,'Pipeline belum dijalankan')}
      function evidence(){return pageHead('Evidence Card','Rangkuman bukti yang bisa ditelusuri dan diuji',btn('Sumber & metode · PDF','go-sources'))+`<div class="metrics">${metric('Status','INSUFFICIENT_EVIDENCE','Engine belum dijalankan/tervalidasi')}${metric('Sample size','Belum tersedia','Definisi event/cohort belum dijalankan')}${metric('Confidence interval','Belum tersedia','Tidak mengarang angka')}${metric('Baseline delta','Belum tersedia','Belum diuji')}</div>`+`<div class="split">${section('Input bukti FOUND',`<p class="note">Universe dan daily OHLCV 45/45; foreign flow untuk histori provider; broker activity per emiten sesuai scope; 341 filing records; news untuk jendela yang diminta; corporate actions 45/45; riwayat suspensi 45 simbol ditanya dengan 2 event WIFI. IHSG kini tersambung dari 13 snapshot lokal Sectors.app (25 Sep 2023–24 Sep 2026); ketersediaan input tidak sama dengan kesimpulan analitik.</p>`)}${section('Counter-thesis & falsifier',`<p class="note">Tampilkan kontra-bukti, tanggal ketersediaan data, sampel, definisi metrik, dan kondisi pembatal thesis. Broker flow tidak membuktikan beneficial owner atau niat.</p>`)}</div>`+section('Batas bukti yang memengaruhi kesimpulan',`<p class="note">Foreign flow baru tersedia mulai 2 Jan 2025. Report bertanggal harga 25 Sep sedangkan daily berakhir 24 Sep; jaga point-in-time alignment. IHSG tersedia sebagai input benchmark; klasifikasi regime, breadth, dan outcome belum dihitung atau divalidasi.</p>`,btn('Buka Evidence Ledger','go-ledger'))}
      function outcomes(){return pageHead('Outcomes & Historical Analog','Validasi hasil lampau dengan horizon dan pembanding yang dinyatakan jelas',btn('Horizon 5D ▾','horizon'))+`<div class="metrics">${metric('Daily history','45 ticker','44 mulai 25 Sep 2023; AADI 5 Des 2024; akhir 24 Sep 2026')}${metric('Benchmark IHSG','INPUT TERSAMBUNG','13 snapshot lokal; cakupan 25 Sep 2023–24 Sep 2026')}${metric('Forward return','Belum dihitung','Perlu event, horizon, dan aturan tanggal')}${metric('Hit rate / CI','Belum tersedia','Tidak tampil sampai uji dijalankan')}</div>`+section('Forward return versus baseline',`<p class="note">Panel ini belum memiliki hasil terukur. IHSG sudah tersedia sebagai benchmark input; ukur per ticker dan horizon dengan baseline sama, confidence interval, serta failure cases sebelum menampilkan hasil.</p>`,'Belum diuji')+section('Failure cases',`<p class="note">Negative-result registry belum berisi hasil pipeline. Setiap run harus mencatat sinyal gagal, missing input, versi model, dan batas sampel.</p>`,btn('Buka Studies','go-studies'))}
      function watchlistAnalysisRows(){return new Map((dashboardData.screener_analysis?.rows||[]).map(row=>[row.ticker,row]))}
      function watchlistSortValue(row,key){const datum=row.analysis;switch(key){case'ticker':return row.ticker;case'company':return row.company;case'flow':return datum?.flow_strength_z20;case'sample':return datum?.event_count;case'outcome5':return datum?.outcome_5d;case'outcome20':return datum?.outcome_20d;case'hit':return datum?.hit_rate;case'interval':return Array.isArray(datum?.hit_rate_ci95)?(datum.hit_rate_ci95[0]+datum.hit_rate_ci95[1])/2:null;case'delta':return datum?.baseline_delta_20d;case'regime':return datum?.regime?.label;case'asof':return datum?.as_of;default:return row.ticker}}
      function watchlistSortedRows(){const symbols=new Map(screenerRows().map(row=>[row.ticker,row])),analysis=watchlistAnalysisRows(),rows=watchlistTickers.map(code=>({ticker:code,company:symbols.get(code)?.company||code,analysis:analysis.get(code)}));return rows.sort((a,b)=>{const av=watchlistSortValue(a,watchlistSort.key),bv=watchlistSortValue(b,watchlistSort.key);if(av==null)return bv==null?a.ticker.localeCompare(b.ticker):1;if(bv==null)return-1;const result=typeof av==='number'&&typeof bv==='number'?av-bv:String(av).localeCompare(String(bv),'id');return result*(watchlistSort.direction==='asc'?1:-1)})}
      function watchlistSortButton(label,key){const active=watchlistSort.key===key,indicator=active?(watchlistSort.direction==='asc'?'↑':'↓'):'↕';return `<button class="watchlist-sort" data-action="watchlist-sort" data-sort-key="${key}" aria-label="Urutkan ${label} ${active?(watchlistSort.direction==='asc'?'menurun':'menaik'):'menaik'}">${label}<span class="watchlist-sort-indicator" aria-hidden="true">${indicator}</span></button>`}
      function watchlistPercent(value,digits=2){return Number.isFinite(value)?`${value>=0?'+':''}${(value*100).toFixed(digits)}%`:'—'}
      function watchlistRowsMarkup(){const rows=watchlistSortedRows();if(!rows.length)return `<div class="watchlist-empty"><div class="watchlist-empty-mark" aria-hidden="true">☆</div><h2>Watchlist kamu masih kosong</h2><p>Simpan emiten yang ingin kamu pantau dari snapshot universe LQ45 lokal.</p></div><button class="watchlist-more" data-action="watchlist-open-picker">⌕&nbsp; Cari emiten lainnya</button>`;return `<div class="watchlist-table-wrap"><table class="watchlist-table"><thead><tr><th>#</th><th>${watchlistSortButton('Ticker','ticker')}</th><th>${watchlistSortButton('Emiten','company')}</th><th>${watchlistSortButton('Flow Strength · Z20','flow')}</th><th>${watchlistSortButton('Sample','sample')}</th><th>${watchlistSortButton('5D Outcome','outcome5')}</th><th>${watchlistSortButton('20D Outcome','outcome20')}</th><th>${watchlistSortButton('Hit Rate','hit')}</th><th>${watchlistSortButton('Confidence Interval 95%','interval')}</th><th>${watchlistSortButton('Baseline Delta','delta')}</th><th>${watchlistSortButton('Regime emiten','regime')}</th><th>${watchlistSortButton('As of','asof')}</th><th></th></tr></thead><tbody>${rows.map((row,index)=>{const item=row.analysis,ci=item?.hit_rate_ci95,delta=item?.baseline_delta_20d;return `<tr data-action="open-issuer" data-ticker="${escapeHTML(row.ticker)}" tabindex="0"><td class="muted-cell">${index+1}</td><td class="ticker">${escapeHTML(row.ticker)}</td><td>${escapeHTML(row.company)}</td><td>${Number.isFinite(item?.flow_strength_z20)?`${item.flow_strength_z20>=0?'+':''}${item.flow_strength_z20.toFixed(2)}σ`:'Belum dihitung'}</td><td>${item?`${item.sample_5d} / ${item.sample_20d}${item.sample_status==='SMALL_SAMPLE'?'<small class="note" style="display:block">Sampel kecil</small>':''}`:'Belum tersedia'}</td><td>${watchlistPercent(item?.outcome_5d)}</td><td>${watchlistPercent(item?.outcome_20d)}</td><td>${Number.isFinite(item?.hit_rate)?`${(item.hit_rate*100).toFixed(1)}%`:'Belum diukur'}</td><td>${Array.isArray(ci)?`${(ci[0]*100).toFixed(1)}% – ${(ci[1]*100).toFixed(1)}%`:'Belum diukur'}</td><td>${Number.isFinite(delta)?`${delta>=0?'+':''}${(delta*100).toFixed(2)} pp`:'—'}</td><td>${escapeHTML(item?.regime?.label||'Belum dihitung')}</td><td>${escapeHTML(item?.as_of||'—')}</td><td><button class="watchlist-remove" data-action="watchlist-remove" data-ticker="${escapeHTML(row.ticker)}" aria-label="Hapus ${escapeHTML(row.ticker)} dari Watchlist">Hapus</button></td></tr>`}).join('')}</tbody></table></div><button class="watchlist-more" data-action="watchlist-open-picker">⌕&nbsp; Cari emiten lainnya</button>`}
      function watchlist(){const count=watchlistTickers.length,asOf=dashboardData.screener_analysis?.as_of;return pageHead('Watchlist','Pantau emiten pilihanmu dan ringkasan data historisnya',btn('＋ Tambah emiten','watchlist-open-picker','action primary'))+section(`Emiten tersimpan · ${count}`,`${watchlistRowsMarkup()}<p class="note">Snapshot LQ45 lokal${asOf?` · data per ${escapeHTML(asOf)}`:''}. Sampel, hasil historis, dan regime bersifat deskriptif; kolom dapat diurutkan naik/turun dengan menekan judulnya.</p>`,'DATA LOKAL · BUKAN REAL-TIME')}
