      function renderWatchlistPicker(){const host=root.querySelector('#watchlist-picker-list'),count=root.querySelector('#watchlist-picker-count');if(!host)return;const query=watchlistQuery.trim().toLocaleLowerCase(),rows=screenerRows().filter(row=>!query||`${row.ticker} ${row.company}`.toLocaleLowerCase().includes(query));host.innerHTML=rows.length?rows.map(row=>{const selected=watchlistTickers.includes(row.ticker);return `<div class="watchlist-picker-row"><span class="ticker">${escapeHTML(row.ticker)}</span><span class="sub">${escapeHTML(row.company)}</span><button class="action ${selected?'ghost':''}" data-action="watchlist-toggle" data-ticker="${escapeHTML(row.ticker)}" ${selected?'aria-pressed="true"':''}>${selected?'Ditambahkan':'＋ Tambah'}</button></div>`}).join(''):`<p class="search-empty">Tidak ada emiten yang cocok dengan pencarian.</p>`;if(count)count.textContent=`${watchlistTickers.length} emiten dipilih · snapshot LQ45`}
