          '<div class="sector-heatmap-legend"><span>Positif</span><i aria-hidden="true"></i><span>Negatif</span></div><p class="sector-heatmap-legend-note">Kuning ≈ 0% · skala simetris persentil ke-95 return harian</p><div class="sector-heatmap-tooltip" role="status" hidden></div></div>':
          '<div class="dashboard-placeholder"><div><strong>Heatmap belum tersedia</strong>Snapshot lokal belum memiliki pasangan harga harian yang cukup untuk jendela bulanan.</div></div>';
