      function updateHistoryControls(){const back=root.querySelector('[data-action="history-back"]'),forward=root.querySelector('[data-action="history-forward"]');if(back)back.disabled=appHistoryIndex<=0;if(forward)forward.disabled=appHistoryIndex<0||appHistoryIndex>=appHistory.length-1}
