          if(svg.dataset.interactionMounted==='true')return;svg.dataset.interactionMounted='true';
          const bounds=options.plotBounds(svg),observations=options.observations(svg).filter(point=>Number.isFinite(point.x)&&Number.isFinite(point.y)).sort((a,b)=>a.x-b.x);if(!observations.length)return;
          const ns='http://www.w3.org/2000/svg',vertical=document.createElementNS(ns,'line'),horizontal=document.createElementNS(ns,'line');
          vertical.setAttribute('class','historical-crosshair historical-crosshair-x');horizontal.setAttribute('class','historical-crosshair historical-crosshair-y');
          for(const line of [vertical,horizontal]){line.setAttribute('visibility','hidden');svg.appendChild(line)}
          vertical.setAttribute('y1',bounds.top);vertical.setAttribute('y2',bounds.bottom);horizontal.setAttribute('x1',bounds.left);horizontal.setAttribute('x2',bounds.right);
          const frame=svg.parentElement;frame.classList.add('historical-chart-frame');const tooltip=document.createElement('div');tooltip.className='chart-interaction-tooltip';tooltip.setAttribute('role','status');tooltip.setAttribute('aria-live','polite');tooltip.setAttribute('hidden','');frame.appendChild(tooltip);
          let selected=-1;const closestObserved=x=>{let lo=0,hi=observations.length;while(lo<hi){const mid=(lo+hi)>>1;if(observations[mid].x<x)lo=mid+1;else hi=mid}const a=Math.max(0,lo-1),b=Math.min(observations.length-1,lo);return Math.abs(observations[a].x-x)<=Math.abs(observations[b].x-x)?a:b};
          const show=(index,event)=>{selected=Math.max(0,Math.min(observations.length-1,index));const point=observations[selected];vertical.setAttribute('x1',point.x);vertical.setAttribute('x2',point.x);horizontal.setAttribute('y1',point.y);horizontal.setAttribute('y2',point.y);vertical.setAttribute('visibility','visible');horizontal.setAttribute('visibility','visible');tooltip.textContent=options.formatter(point);tooltip.hidden=false;const frameRect=frame.getBoundingClientRect(),leftFromPointer=event?event.clientX-frameRect.left+10:point.x/bounds.viewWidth*svg.clientWidth+8,topFromPointer=event?event.clientY-frameRect.top-tooltip.offsetHeight-10:point.y/bounds.viewHeight*svg.clientHeight-tooltip.offsetHeight-8,left=Math.max(4,Math.min(frame.clientWidth-tooltip.offsetWidth-4,leftFromPointer)),top=Math.max(4,Math.min(frame.clientHeight-tooltip.offsetHeight-4,topFromPointer));tooltip.style.left=left+'px';tooltip.style.top=top+'px'};
          svg.addEventListener('pointermove',event=>{if(event.buttons)return;const rect=svg.getBoundingClientRect(),x=(event.clientX-rect.left)/rect.width*bounds.viewWidth+bounds.left;show(closestObserved(x),event)});
