        const ticks=[-2,-1,0,1,2].filter(value=>Math.abs(value)<=limit),axis=ticks.map(value=>`<line x1="${x(value)}" y1="${top-6}" x2="${x(value)}" y2="${height-bottom+1}" stroke="${value===0?'#8fa2b7':'#30445a'}" stroke-width="${value===0?1.5:1}" stroke-dasharray="${value===0?'':'3 5'}"/><text x="${x(value)}" y="${height-10}" text-anchor="middle" fill="#8fa2b7" font-size="10">${value>0?'+':''}${value}σ</text>`).join('');
