        const sorted=losses.map(row=>row.value).sort((a,b)=>a-b),quantile=p=>{const pos=(sorted.length-1)*p,lo=Math.floor(pos),hi=Math.ceil(pos);return sorted[lo]+(sorted[hi]-sorted[lo])*(pos-lo)},q95=quantile(.95),tailCount=losses.filter(row=>row.value>q95).length;
