        losses.forEach(row=>{const i=Math.min(bins-1,Math.max(0,Math.floor((row.value-min)/binWidth)));counts[i]++});
        const W=1120,H=390,L=66,R=24,T=26,B=62,plotW=W-L-R,plotH=H-T-B,peak=Math.max(1,...counts),x=v=>L+(v-min)/span*plotW,y=v=>T+plotH-v/peak*plotH,barW=plotW/bins;
        let marks='';counts.forEach((count,i)=>{const x0=L+i*barW,center=min+(i+.5)*binWidth,tail=center>=q95,color=tail?'#e4777b':'#5e86a8',range=`${((min+i*binWidth)*100).toFixed(2)}%–${((min+(i+1)*binWidth)*100).toFixed(2)}%`;marks+=`<rect data-evt-bin="true" data-range="${range}" data-count="${count}" data-tail="${tail?'yes':'no'}" x="${(x0+1).toFixed(1)}" y="${y(count).toFixed(1)}" width="${Math.max(1,barW-2).toFixed(1)}" height="${(T+plotH-y(count)).toFixed(1)}" rx="2" fill="${color}" opacity="${tail?'.94':'.78'}"><title>${range} · ${count} sesi${tail?' · ekor di atas p95':''}</title></rect>`});
        const grid=[0,.25,.5,.75,1].map(f=>{const yy=T+plotH*(1-f),value=Math.round(peak*f);return `<line x1="${L}" y1="${yy}" x2="${W-R}" y2="${yy}" stroke="#405165" stroke-opacity=".5" stroke-dasharray="4 5"/><text x="${L-10}" y="${yy+4}" fill="#9aadc0" font-size="11" text-anchor="end">${value}</text>`}).join('');
        const ticks=[min,min+span/4,min+span/2,min+span*3/4,max].map(v=>`<line x1="${x(v)}" y1="${T+plotH}" x2="${x(v)}" y2="${T+plotH+5}" stroke="#8296aa"/><text x="${x(v)}" y="${T+plotH+24}" fill="#9aadc0" font-size="11" text-anchor="middle">${(v*100).toFixed(0)}%</text>`).join('');
        const threshold=`<line x1="${x(q95)}" y1="${T}" x2="${x(q95)}" y2="${T+plotH}" stroke="#ffc86b" stroke-width="1.25" stroke-dasharray="7 5"><title>Ambang empiris p95: ${(q95*100).toFixed(2)}%</title></line><text x="${Math.min(W-R-4,x(q95)+7)}" y="${T+14}" fill="#ffc86b" font-size="12" font-weight="700">p95 ${(q95*100).toFixed(2)}%</text>`;
        const chart=`<div class="evt-chart-wrap"><svg class="evt-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Histogram kerugian harian IHSG, ${losses.length} return harian. Area ekor di atas ambang empiris persentil 95 disorot.">${grid}${marks}${threshold}${ticks}<text x="${L+plotW/2}" y="${H-10}" fill="#aab8c8" font-size="12" text-anchor="middle">Kerugian harian (−log return; negatif berarti sesi naik)</text><text x="17" y="${T+plotH/2}" fill="#aab8c8" font-size="11" text-anchor="middle" transform="rotate(-90 17 ${T+plotH/2})">Jumlah sesi</text></svg></div>`;
        const probeMatches=data.coverage_end==='2026-09-24'&&Number(data.observation_count)===708&&data.retrieved_at==='2026-09-27T16:43:12.252647+00:00';
