        const surfaceExplanation=`<div class="evt-surface-explanation"><strong>Cara membaca surface 3D.</strong> Sumbu X menunjukkan akhir bulan, Y menunjukkan kuantil empiris (p90–p97,5), dan Z serta warna menunjukkan besarnya loss harian pada jendela 252 sesi sebelumnya. Permukaan yang meninggi berarti ambang loss historis pada jendela itu membesar; ini deskripsi ekor return masa lalu, bukan probabilitas crash atau ramalan. Data bulanan diperbarui dari snapshot MATLAB yang sama dengan interaksi kamera live.</div>`;
        const histogramNote=`<p class="evt-note"><b>Cara membaca histogram.</b> Ini melengkapi surface: batang menunjukkan sebaran seluruh ${losses.length} return harian, ekor merah berada di atas ambang empiris p95 ${(q95*100).toFixed(2)}%, dan garis amber hanya penanda ambang—bukan stop atau sinyal. ${escapeHTML(caveat)} Belum diuji out-of-sample atau untuk keputusan trading. Sumber: snapshot lokal Sectors.app · IHSG harian · ${Number(data.observation_count)} penutupan.</p>`;
        const histogramPanel=`<section class="evt-secondary-visual"><div class="evt-visual-heading"><div><h3>Distribusi return harian · konteks ekor</h3><p>Histogram seluruh sesi, dengan ambang p95 dan observasi ekor ditandai.</p></div><span class="evt-visual-meta">${losses.length} return · p95 ${(q95*100).toFixed(2)}%</span></div>${chart}${histogramNote}</section>`;
        const displayBody=`${body}<div class="evt-visual-stack"><section class="evt-primary-visual"><div class="evt-visual-heading"><div><h3>Surface tail-loss historis · MATLAB live</h3><p>Visualisasi utama: evolusi ambang loss empiris IHSG pada rolling window 252 sesi.</p></div><span class="evt-visual-meta">${surface?.ok?'24 akhir bulan · 4 kuantil · sudut kamera tersinkron':'GRID BELUM TERSEDIA'}</span></div>${surfaceView}${surfaceExplanation}</section>${histogramPanel}</div>`;
        return section('IHSG · EVT tail-risk explorer',displayBody,'INTERAKTIF · MATLAB DATA · BUKAN PROBABILITAS CRASH','market-wide evt-panel');
