      function marketRegimePanel(compact=false){
        const data=dashboardData.ihsg,series=(data?.series||[]).filter(item=>Number.isFinite(Number(item.price))&&Number(item.price)>0);
        const unavailable=message=>section('Market regime · IHSG',`<div class="market-data-placeholder"><div><strong>Regime belum dapat dihitung</strong>${message}</div></div>`,'INSUFFICIENT EVIDENCE');
        if(!data?.ok)return unavailable('Snapshot IHSG lokal belum tersedia.');
        if(series.length<201)return unavailable(`Perlu minimal 201 penutupan harian; saat ini tersedia ${series.length}.`);
        const prices=series.map(item=>Number(item.price)),last=prices.at(-1),mean=(start,end)=>prices.slice(start,end).reduce((sum,value)=>sum+value,0)/(end-start);
        const sma50=mean(prices.length-50,prices.length),sma200=mean(prices.length-200,prices.length);
        const label=last>sma200&&sma50>sma200?'Tren menguat':last<sma200&&sma50<sma200?'Tren melemah':'Tren campuran';
        const color=label==='Tren menguat'?'#49c99e':label==='Tren melemah'?'#e4777b':'#ffc86b';
        const returns=[];for(let i=1;i<prices.length;i++)returns.push(prices[i]/prices[i-1]-1);
        const windowVol=[];for(let end=20;end<=returns.length;end++){const window=returns.slice(end-20,end),avg=window.reduce((sum,value)=>sum+value,0)/window.length,variance=window.reduce((sum,value)=>sum+(value-avg)**2,0)/(window.length-1);windowVol.push(Math.sqrt(variance*252));}
        if(!windowVol.length)return unavailable('Riwayat return belum cukup untuk menghitung volatilitas 20 sesi.');
        const currentVol=windowVol.at(-1),rank=100*windowVol.filter(value=>value<=currentVol).length/windowVol.length,marker=Math.max(0,Math.min(100,rank));
        const volBand=rank<25?'relatif rendah':rank>75?'relatif tinggi':'sekitar tengah';
        if(compact)return section('Market Regime · IHSG',`<div class="dashboard-summary-kpi" style="color:${color}">${label}</div><div class="dashboard-meta">Close & SMA 50 dibanding SMA 200</div><div class="dashboard-summary-pair"><span>Volatilitas 20 sesi</span><b>${(currentVol*100).toFixed(1)}% p.a.</b></div><div class="market-regime-vol-track" role="img" aria-label="Persentil volatilitas ${rank.toFixed(0)} dari 100"><span class="market-regime-vol-marker" style="left:${marker.toFixed(1)}%"></span></div><div class="market-regime-vol-labels"><span>Rendah</span><span>p${rank.toFixed(0)} · ${volBand}</span><span>Tinggi</span></div><p class="dashboard-meta">${escapeHTML(data.coverage_end)} · baseline deskriptif, bukan forecast.</p>`,btn('Detail pasar','go-market'),'dashboard-regime-summary');
        const date=escapeHTML(data.coverage_end||series.at(-1).date),fmt=value=>Number(value).toLocaleString('id-ID',{minimumFractionDigits:2,maximumFractionDigits:2});
        const body=`<div class="market-regime"><div class="market-regime-state" style="--regime-color:${color}"><strong>${label}</strong><small>Aturan tren: posisi IHSG dan SMA 50 sesi dibandingkan SMA 200 sesi.</small></div><div class="market-regime-metrics"><div><small>IHSG · ${date}</small><b>${fmt(last)}</b></div><div><small>SMA 50 sesi</small><b>${fmt(sma50)}</b></div><div><small>SMA 200 sesi</small><b>${fmt(sma200)}</b></div></div><div class="market-regime-vol"><div class="row"><b>Volatilitas 20 sesi</b><span>${currentVol.toLocaleString('id-ID',{style:'percent',maximumFractionDigits:1})} p.a. · ${volBand}</span></div><div class="market-regime-vol-track" role="img" aria-label="Volatilitas IHSG 20 sesi berada pada persentil ${rank.toFixed(0)} dibanding rolling history"><span class="market-regime-vol-marker" style="left:${marker.toFixed(1)}%"></span></div><div class="market-regime-vol-labels"><span>rendah · p0</span><span>p${rank.toFixed(0)} dari rolling history · tinggi p100</span></div></div><p class="note">Snapshot lokal Sectors.app · ${series.length} penutupan (${escapeHTML(data.coverage_start)}–${date}). Volatilitas = simpangan baku return 20 sesi disetahunkan; persentil dibandingkan jendela 20 sesi pada snapshot yang sama.</p><p class="note">Label tren adalah baseline teknikal deskriptif, bukan klasifikasi tervalidasi atau ramalan. “Campuran” berarti arah harga dan susunan SMA tidak sejalan.</p></div>`;
        return section('Market regime · IHSG',body,'BASELINE DESKRIPTIF · BUKAN FORECAST');
      }
      function currentScreenerRegime(){
        const series=(dashboardData.ihsg?.series||[]).filter(item=>Number.isFinite(Number(item.price))&&Number(item.price)>0);
        if(series.length<201)return 'Belum dihitung';
        const prices=series.map(item=>Number(item.price)),last=prices.at(-1);
        const sma50=prices.slice(-50).reduce((sum,value)=>sum+value,0)/50;
        const sma200=prices.slice(-200).reduce((sum,value)=>sum+value,0)/200;
        return last>sma200&&sma50>sma200?'Tren menguat':last<sma200&&sma50<sma200?'Tren melemah':'Tren campuran';
      }
