        const definition=kind==='sharpe'?'mean excess return tahunan ÷ volatilitas tahunan':'CAGR kumulatif ÷ |maximum drawdown kumulatif|',extra=kind==='calmar'?' Nilai awal dapat bergerak tajam saat drawdown maksimum berubah.':' Risk-free memakai asumsi tahunan manual.';
        return `<svg class="portfolio-risk-svg" data-chart-interaction viewBox="0 0 ${W} ${H}" tabindex="0" role="img" aria-label="Riwayat ${title} ekspanding dari ${escapeHTML(series[0].date)} sampai ${escapeHTML(series.at(-1).date)}; nilai terakhir ${series.at(-1).value.toFixed(2)} kali. Perhitungan kumulatif dimulai setelah 20 return harian dan bersifat deskriptif, bukan prediksi."><title>Riwayat ${title} ekspanding</title><desc>${escapeHTML(definition)} dihitung dari awal sampel sampai setiap tanggal. Arahkan kursor ke titik untuk tanggal dan nilai rasio.</desc>${ticks}<line x1="${L}" y1="${zeroY.toFixed(1)}" x2="${W-R}" y2="${zeroY.toFixed(1)}" stroke="#91a5bb" stroke-width="1.2"/><polyline points="${line}" fill="none" stroke="${kind==='sharpe'?'#65a8ff':'#49c99e'}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>${marks}<text transform="translate(12 ${H/2}) rotate(-90)" text-anchor="middle" fill="#91a5bb" font-size="9">${title} · rasio (×)</text><text x="${L}" y="${H-9}" fill="#a9bbcd" font-size="9">${escapeHTML(series[0].date)}</text><text x="${W-R}" y="${H-9}" text-anchor="end" fill="#a9bbcd" font-size="9">${escapeHTML(series.at(-1).date)}</text></svg><div class="portfolio-risk-legend"><span><i style="background:${kind==='sharpe'?'#65a8ff':'#49c99e'}"></i>${title} ekspanding · ${series.length} sesi</span><span>Garis nol = rasio 0×</span></div><p class="note">Ekspanding dari awal sampel · rasio ditampilkan setelah terkumpul minimal 20 sesi · ${escapeHTML(definition)}.${extra} Seri in-sample historis, bukan kinerja masa depan.</p>`;
