        return `<svg class="portfolio-risk-svg" data-chart-interaction viewBox="0 0 ${W} ${H}" tabindex="0" role="img" aria-label="Distribusi kepadatan ${returns.length} return harian; area downside di bawah target ${targetLabel} per tahun diarsir. Kurva KDE deskriptif; titik menandai return aktual."><title>Distribusi return dan downside Sortino</title><desc>Area downside di bawah target minimum diarsir; garis vertikal menunjukkan target minimum. Titik hover menunjukkan tanggal dan return aktual.</desc><line x1="${L}" y1="${H-B}" x2="${W-R}" y2="${H-B}" stroke="#71869a"/><line x1="${L}" y1="${T+(H-T-B)/2}" x2="${W-R}" y2="${T+(H-T-B)/2}" stroke="#284054" stroke-dasharray="3 4"/><polygon points="${downsidePoints}" fill="#e4777b" opacity=".25"/><polyline points="${curve}" fill="none" stroke="#65a8ff" stroke-width="1.5"/>${sampleMarks}<line x1="${targetX.toFixed(1)}" y1="${T}" x2="${targetX.toFixed(1)}" y2="${H-B}" stroke="#ffc86b" stroke-width="1.25" stroke-dasharray="3 3"><title>Target minimum ${targetLabel} p.a.</title></line><text x="${Math.max(L+4,Math.min(W-R-4,targetX+5)).toFixed(1)}" y="${T+10}" fill="#ffc86b" font-size="10">Target ${targetLabel} p.a.</text><text x="${L}" y="${H-9}" fill="#a9bbcd" font-size="10">${minLabel}</text><text x="${W-R}" y="${H-9}" text-anchor="end" fill="#a9bbcd" font-size="10">${maxLabel}</text><text x="${W/2}" y="${H-9}" text-anchor="middle" fill="#8498ad" font-size="9">Return harian</text></svg><div class="portfolio-risk-legend"><span><i style="background:#e4777b"></i>Area downside di bawah target</span><span><i style="background:#65a8ff"></i>Kepadatan return empiris (KDE)</span></div><p class="note">${returns.length} return harian · target minimum ${targetLabel} p.a. · bentuk distribusi deskriptif, bukan kurva probabilitas ke depan.</p>`;
