          ctx.font='600 14px Inter,-apple-system,sans-serif';ctx.fillStyle='#e4ebf2';const xLabel=project(0,-3,-3),yLabel=project(-3,0,-3),zLabel=project(-3,-3,0);ctx.textAlign='center';ctx.fillText('X · Value · earnings/dividend yield',xLabel.x+34,xLabel.y+48);ctx.save();ctx.translate(yLabel.x-56,yLabel.y+10);ctx.rotate(-Math.PI/3.7);ctx.fillText('Y · Momentum · 12-1 return / MA200',0,0);ctx.restore();ctx.save();ctx.translate(zLabel.x-62,zLabel.y);ctx.rotate(-Math.PI/2);ctx.fillText('Z · Quality · ROE / inverse DER',0,0);ctx.restore();
