      function invalidatePortfolioResult(){portfolioState.requestGeneration++;portfolioState.result=null;portfolioState.error=null;portfolioState.loading=false}
      function localApiFailureMessage(route,error){
        const detail=error?.message?` (${error.message})`:'';
        return `API lokal ${route} tidak merespons${detail}. Pastikan task “IDX Evidence Lab: Local API (5501)” berjalan dan proxy /api aktif; halaman tetap di 127.0.0.1:5500. Coba lagi.`
      }
      async function loadPortfolioData(){
        if(portfolioState.catalog||portfolioState.catalogLoading||portfolioState.catalogAttempted)return;
        portfolioState.catalogLoading=true;portfolioState.catalogAttempted=true;
        try{const response=await fetch(portfolioApiUrl('/api/portfolio-data'),{cache:'no-store'});if(!response.ok)throw new Error('HTTP '+response.status);const catalog=await response.json();if(!Array.isArray(catalog.tickers)||!catalog.tickers.length)throw new Error('Katalog tidak berisi saham.');portfolioState.catalog=catalog;portfolioState.catalogError=null}
        catch(error){portfolioState.catalogError=localApiFailureMessage('/api/portfolio-data',error)}
        finally{portfolioState.catalogLoading=false;if(page==='portfolio-lab')render()}
      }
      async function runPortfolioAnalysis(formState){
        const requestGeneration=++portfolioState.requestGeneration;
        const payload={tickers:[...formState.selected],benchmark:'IHSG',profile:formState.profile,method:'integrated',lookback:252,constraints:{},total_capital:formState.capital===''?null:Number(formState.capital),risk_free_annual:formState.riskFreeRatePct===''?null:Number(formState.riskFreeRatePct)/100,market_premium_annual:null,scenarios:{horizons:[20,60,120],simulations:300,seed:42,block_size:5,drawdown_threshold:null}};
        portfolioState.loading=true;portfolioState.error=null;portfolioState.result=null;render();
        try{const response=await fetch(portfolioApiUrl('/api/portfolio-analysis'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),cache:'no-store'});const result=await response.json();if(requestGeneration!==portfolioState.requestGeneration)return;if(!response.ok)throw new Error(result.error||'Perhitungan lokal belum tersedia.');portfolioState.result=result}
        catch(error){if(requestGeneration===portfolioState.requestGeneration)portfolioState.error=localApiFailureMessage('/api/portfolio-analysis',error)}
        finally{if(requestGeneration===portfolioState.requestGeneration){portfolioState.loading=false;if(page==='portfolio-lab')render()}}
      }
      root.addEventListener('change',e=>{if(e.target.matches('[data-action="market-rsi-period"]')){marketRsiPeriod=Number(e.target.value);render()}if(e.target.matches('[data-action="market-rsi-range"]')){marketRsiRange=e.target.value;render()}});
      root.addEventListener('change',e=>{if(e.target.matches('#dossier-event-select')){dossierEvent=e.target.value;render()}if(e.target.matches('#foreign-month-range')){marketFlowMonths=Number(e.target.value);render()}});
