      root.addEventListener('change',e=>{const key=e.target.dataset.portfolioField;if(!key)return;portfolioState[key]=e.target.value;invalidatePortfolioResult();if(['capital','riskFreeRatePct'].includes(key)&&portfolioState.selected.length){runPortfolioAnalysis({...portfolioState});return}render()});
