      function mountNewsGraph(){const frame=root.querySelector('.news-graph');if(!frame)return;frame.dataset.graphNewsId=newsGraph.news_id||'';const canvas=document.createElement('canvas');canvas.setAttribute('aria-label','Peta hipotesis berita 3D offline; drag untuk rotasi, shift-drag untuk pan, scroll untuk zoom');canvas.setAttribute('role','img');frame.appendChild(canvas);const controls=document.createElement('div');controls.className='row news-graph-controls';controls.innerHTML='<button class="action" data-action="news-pan-toggle" aria-pressed="false">Pan: off</button><button class="action" data-action="news-zoom-out" aria-label="Zoom out">−</button><button class="action" data-action="news-zoom-in" aria-label="Zoom in">+</button><button class="action" data-action="news-graph-reset">Reset view</button><button class="action" data-action="news-tree-toggle">Tree view</button>';frame.after(controls);const count=root.querySelector('#news-graph-count');controls.after(count);const tree=root.querySelector('#news-tree-content');if(tree){const nodes=newsGraph.nodes||[];const obs=nodes.filter(function(node){return node.kind!=='hypothesis'});const hyps=nodes.filter(function(node){return node.kind==='hypothesis'});tree.innerHTML='<p class="note"><b>Fakta teks/metadata:</b> '+(obs.map(function(n){return escapeHTML(n.label)}).join(' · ')||'tidak terdeteksi')+'</p><p class="note"><b>Jalur hipotesis (belum diverifikasi):</b> '+(hyps.map(function(n){return escapeHTML(n.label)}).join(' · ')||'belum ada jalur yang cukup didukung oleh kata/tautan di artikel ini')+'</p><p class="note">'+escapeHTML((newsData?.articles||[]).find(function(a){return a.news_id===newsGraph.news_id})?.offline_analysis?.limitations||'Pilih artikel. Tidak ada hubungan kausal yang diasumsikan.')+'</p>'}drawNewsGraph(canvas,newsGraph);if(typeof ResizeObserver==='function'){new ResizeObserver(function(){drawNewsGraph(canvas,newsGraph)}).observe(frame)}}
